IPC_HANDLERS_SNIPPET = '\n\n    // ANTIGRAVITY_OFFICE_IPC_HANDLERS\n    function __toCleanLocalPath(raw) {\n        if (!raw || typeof raw !== \'string\') return null;\n        let p = raw.split(\'#\')[0].split(\'?\')[0].trim();\n        if (p.startsWith(\'file://\')) {\n            try {\n                const { fileURLToPath } = require(\'url\');\n                p = fileURLToPath(p);\n            } catch (e) {}\n        }\n        try { p = decodeURIComponent(p); } catch (e) {}\n        p = p.replace(/^file:[\\/]+/i, \'\');\n        p = require(\'path\').normalize(p);\n        return p;\n    }\n\n    function __smartResolveLocalPath(raw) {\n        const cleanPath = __toCleanLocalPath(raw);\n        if (!cleanPath) return null;\n        const fsNode = require(\'fs\');\n        const pathNode = require(\'path\');\n        if (fsNode.existsSync(cleanPath)) {\n            return { path: cleanPath, isHealed: false, isFile: true };\n        }\n\n        const fileName = pathNode.basename(cleanPath);\n        const ext = pathNode.extname(cleanPath).toLowerCase();\n        let baseKey = fileName.slice(0, fileName.lastIndexOf(\'.\') || fileName.length);\n        const parenIdx = baseKey.search(/[（(]/);\n        if (parenIdx !== -1) {\n            baseKey = baseKey.slice(0, parenIdx).trim();\n        }\n\n        let cur = pathNode.dirname(cleanPath);\n        let ancestor = null;\n        while (cur && cur !== pathNode.dirname(cur)) {\n            if (fsNode.existsSync(cur)) {\n                ancestor = cur;\n                break;\n            }\n            cur = pathNode.dirname(cur);\n        }\n\n        if (!ancestor) return { path: cleanPath, isHealed: false, isFile: false };\n\n        function findMatch(dir, depth) {\n            if (depth > 4) return null;\n            try {\n                const entries = fsNode.readdirSync(dir, { withFileTypes: true });\n                const tokens = baseKey.split(/[-_\\s—·]+/).filter(t => t.length >= 3);\n                for (const ent of entries) {\n                    if (ent.isFile()) {\n                        if (ext && !ent.name.toLowerCase().endsWith(ext)) continue;\n                        if (ent.name.includes(baseKey) || (baseKey.length > 6 && ent.name.includes(baseKey.slice(0, 8)))) {\n                            return { path: pathNode.join(dir, ent.name), isHealed: true, isFile: true };\n                        }\n                        if (tokens.length > 0 && tokens.some(t => ent.name.includes(t))) {\n                            return { path: pathNode.join(dir, ent.name), isHealed: true, isFile: true };\n                        }\n                    }\n                }\n                for (const ent of entries) {\n                    if (ent.isDirectory()) {\n                        const sub = findMatch(pathNode.join(dir, ent.name), depth + 1);\n                        if (sub) return sub;\n                    }\n                }\n            } catch(e) {}\n            return null;\n        }\n\n        const match = findMatch(ancestor, 0);\n        if (match) return match;\n        return { path: ancestor, isHealed: false, isFile: false, nearestDir: ancestor };\n    }\n\n    electron_1.ipcMain.handle(\'antigravity:read-file-bytes\', async (_event, filePath) => {\n        try {\n            const cleanPath = __toCleanLocalPath(filePath);\n            if (!cleanPath) return null;\n            const fsNode = require(\'fs\');\n            let target = cleanPath;\n            if (!fsNode.existsSync(target)) {\n                const resolved = __smartResolveLocalPath(cleanPath);\n                if (resolved && resolved.isFile && fsNode.existsSync(resolved.path)) {\n                    target = resolved.path;\n                }\n            }\n            const buf = await fs.readFile(target);\n            return new Uint8Array(buf.buffer, buf.byteOffset, buf.byteLength);\n        } catch (err) {\n            main_1.default.error(\'antigravity:read-file-bytes failed:\', err);\n            return null;\n        }\n    });\n    electron_1.ipcMain.handle(\'antigravity:read-file-text\', async (_event, filePath) => {\n        try {\n            const cleanPath = __toCleanLocalPath(filePath);\n            if (!cleanPath) return null;\n            const fsNode = require(\'fs\');\n            let target = cleanPath;\n            if (!fsNode.existsSync(target)) {\n                const resolved = __smartResolveLocalPath(cleanPath);\n                if (resolved && resolved.isFile && fsNode.existsSync(resolved.path)) {\n                    target = resolved.path;\n                }\n            }\n            return await fs.readFile(target, \'utf-8\');\n        } catch (err) {\n            main_1.default.error(\'antigravity:read-file-text failed:\', err);\n            return null;\n        }\n    });\n    electron_1.ipcMain.handle(\'antigravity:get-office-asset\', async (_event, assetName) => {\n        try {\n            const assetPath = require("path").join(__dirname, \'office_viewer\', assetName);\n            return await fs.readFile(assetPath, \'utf-8\');\n        } catch (err) {\n            main_1.default.error(\'antigravity:get-office-asset failed:\', err);\n            return null;\n        }\n    });\n    electron_1.ipcMain.handle(\'antigravity:get-conversation-turns\', async (_event, conversationId) => {\n        try {\n            if (!conversationId || typeof conversationId !== \'string\') return [];\n            const safeId = require(\'path\').basename(conversationId);\n            const userProfile = process.env.HOME || process.env.USERPROFILE || \'\';\n            const transcriptPath = require(\'path\').join(userProfile, \'.gemini\', \'antigravity\', \'brain\', safeId, \'.system_generated\', \'logs\', \'transcript.jsonl\');\n            const fsNode = require(\'fs\');\n            if (fsNode.existsSync(transcriptPath)) {\n                const content = await fsNode.promises.readFile(transcriptPath, \'utf8\');\n                const lines = content.split(\'\\n\');\n                const turns = [];\n                let turnNumber = 1;\n                for (const line of lines) {\n                    if (!line.trim()) continue;\n                    try {\n                        const step = JSON.parse(line);\n                        if (step.type === \'USER_INPUT\') {\n                            let prompt = (step.content || \'\').trim();\n                            if (prompt.includes(\'<USER_REQUEST>\')) {\n                                prompt = prompt.split(\'<USER_REQUEST>\')[1].split(\'</USER_REQUEST>\')[0].trim();\n                            }\n                            if (prompt.startsWith(\'<CONTEXT_SUMMARY>\') && prompt.includes(\'</CONTEXT_SUMMARY>\')) {\n                                prompt = prompt.split(\'</CONTEXT_SUMMARY>\')[1].trim();\n                            }\n                            const firstLine = prompt.split(\'\\n\')[0].trim();\n                            turns.push({\n                                turnIndex: turnNumber++,\n                                stepIndex: step.step_index,\n                                createdAt: step.created_at,\n                                prompt: prompt.substring(0, 300),\n                                title: (firstLine.length > 50 ? firstLine.substring(0, 50) + \'...\' : firstLine) || \'（用户输入）\'\n                            });\n                        }\n                    } catch (e) {}\n                }\n                return turns;\n            }\n            return [];\n        } catch (err) {\n            return [];\n        }\n    });\n\n    electron_1.ipcMain.handle(\'antigravity:focus-window\', () => {\n        try {\n            const allWins = electron_1.BrowserWindow.getAllWindows();\n            const win = allWins.find(w => !w.isDestroyed() && w.isVisible()) || allWins[0];\n            if (win && !win.isDestroyed()) {\n                if (win.isMinimized()) win.restore();\n                win.setAlwaysOnTop(true);\n                win.show();\n                win.focus();\n                win.setAlwaysOnTop(false);\n                try {\n                    electron_1.app.focus({ steal: true });\n                } catch (e) {}\n            }\n        } catch (err) {\n            console.error(\'[antigravity:focus-window] Error:\', err);\n        }\n    });\n\n    electron_1.ipcMain.handle(\'antigravity:copy-files-to-clipboard\', async (_event, filePaths) => {\n        try {\n            if (!filePaths || !Array.isArray(filePaths) || filePaths.length === 0) return false;\n            const pathNode = require(\'path\');\n            const fsNode = require(\'fs\');\n            const normalizedPaths = filePaths.map(p => {\n                let clean = p.split(\'#\')[0].split(\'?\')[0];\n                if (clean.startsWith(\'file://\')) {\n                    try {\n                        const { fileURLToPath } = require(\'url\');\n                        clean = fileURLToPath(clean);\n                    } catch(e) {}\n                }\n                return pathNode.resolve(clean);\n            }).filter(p => {\n                try { return fsNode.existsSync(p); } catch(e) { return false; }\n            });\n\n            if (normalizedPaths.length === 0) return false;\n\n            if (process.platform === \'win32\') {\n                const { execFile } = require(\'child_process\');\n                const pathsJson = JSON.stringify(normalizedPaths);\n                const psScript = `\nAdd-Type -AssemblyName System.Windows.Forms\n$paths = ConvertFrom-Json @\'\n${pathsJson}\n\'@\n$data = New-Object System.Windows.Forms.DataObject\n$col = New-Object System.Collections.Specialized.StringCollection\nforeach ($p in $paths) { $col.Add($p) }\n$data.SetFileDropList($col)\n$data.SetText(($paths -join [Environment]::NewLine))\n[System.Windows.Forms.Clipboard]::SetDataObject($data, $true)\n`;\n                const encoded = Buffer.from(psScript, \'utf16le\').toString(\'base64\');\n                await new Promise((resolve) => {\n                    execFile(\'powershell.exe\', [\'-NoProfile\', \'-NonInteractive\', \'-Sta\', \'-EncodedCommand\', encoded], (err) => {\n                        if (err) console.error(\'[copy-files] PowerShell error:\', err);\n                        resolve();\n                    });\n                });\n            } else {\n                electron_1.clipboard.writeText(normalizedPaths.join(\'\\n\'));\n            }\n            return true;\n        } catch (err) {\n            console.error(\'[antigravity:copy-files-to-clipboard] Error:\', err);\n            return false;\n        }\n    });\n\n    electron_1.ipcMain.handle(\'antigravity:get-conversation-workspace\', async (_event, conversationId, sectionId) => {\n        try {\n            const fsNode = require(\'fs\');\n            const pathNode = require(\'path\');\n            const osNode = require(\'os\');\n            const homeDir = osNode.homedir();\n            const configProjDir = pathNode.join(homeDir, \'.gemini\', \'config\', \'projects\');\n            const mapPath = pathNode.join(homeDir, \'.gemini\', \'antigravity\', \'projects_workspace_map.json\');\n\n            const getNativeProjectUri = (pId) => {\n                if (!pId || pId === \'outside-of-project\') return null;\n                const pFile = pathNode.join(configProjDir, `${pId}.json`);\n                if (fsNode.existsSync(pFile)) {\n                    try {\n                        const data = JSON.parse(fsNode.readFileSync(pFile, \'utf8\'));\n                        const uri = data.projectResources?.resources?.[0]?.folderUri;\n                        if (uri) return uri;\n                    } catch(e) {}\n                }\n                return null;\n            };\n\n            // 1. Check official native project config first if sectionId provided\n            if (sectionId && sectionId !== \'outside-of-project\') {\n                const nativeUri = getNativeProjectUri(sectionId);\n                if (nativeUri) {\n                    try {\n                        const curMap = fsNode.existsSync(mapPath) ? JSON.parse(fsNode.readFileSync(mapPath, \'utf8\')) : {};\n                        curMap[sectionId] = nativeUri;\n                        fsNode.writeFileSync(mapPath, JSON.stringify(curMap, null, 2), \'utf8\');\n                    } catch(e) {}\n                    return { ok: true, isProject: true, projectId: sectionId, workspaceUri: nativeUri };\n                }\n            }\n\n            // 2. Query SQLite database for conversation metadata and project association\n            const dbPath = pathNode.join(homeDir, \'.gemini\', \'antigravity\', \'conversation_summaries.db\');\n            if (fsNode.existsSync(dbPath)) {\n                const { execFile } = require(\'child_process\');\n                const pyCode = `\nimport sqlite3, json\nconn = sqlite3.connect(r"${dbPath.replace(/\\\\/g, \'\\\\\\\\\')}")\nc = conn.cursor()\nres = {}\nsec = "${sectionId || \'\'}"\ncid = "${conversationId || \'\'}"\nif sec and sec != "outside-of-project":\n    c.execute("SELECT workspace_uris FROM conversation_summaries WHERE project_id = ? AND workspace_uris != \'\' LIMIT 1", (sec,))\n    r = c.fetchone()\n    if r: res["project_ws"] = r[0]\nif cid:\n    c.execute("SELECT project_id, workspace_uris FROM conversation_summaries WHERE conversation_id = ?", (cid,))\n    r = c.fetchone()\n    if r:\n        res["conv_project_id"] = r[0]\n        res["conv_ws"] = r[1]\nprint(json.dumps(res))\n`;\n                const queryRes = await new Promise((resolve) => {\n                    execFile(\'python\', [\'-c\', pyCode], (err, stdout) => {\n                        if (err || !stdout) resolve({});\n                        else {\n                            try { resolve(JSON.parse(stdout)); } catch(e) { resolve({}); }\n                        }\n                    });\n                });\n\n                // If conversation belongs to a project, FIRST check that project\'s official native config!\n                if (queryRes.conv_project_id && queryRes.conv_project_id !== \'outside-of-project\') {\n                    const convNativeUri = getNativeProjectUri(queryRes.conv_project_id);\n                    if (convNativeUri) {\n                        try {\n                            const curMap = fsNode.existsSync(mapPath) ? JSON.parse(fsNode.readFileSync(mapPath, \'utf8\')) : {};\n                            curMap[queryRes.conv_project_id] = convNativeUri;\n                            fsNode.writeFileSync(mapPath, JSON.stringify(curMap, null, 2), \'utf8\');\n                        } catch(e) {}\n                        return { ok: true, isProject: true, projectId: queryRes.conv_project_id, workspaceUri: convNativeUri };\n                    }\n                }\n\n                if (queryRes.project_ws) {\n                    try {\n                        const parsed = JSON.parse(queryRes.project_ws);\n                        if (parsed && parsed[0]) {\n                            return { ok: true, isProject: true, projectId: sectionId, workspaceUri: parsed[0] };\n                        }\n                    } catch(e) {}\n                }\n\n                if (queryRes.conv_ws) {\n                    try {\n                        const parsed = JSON.parse(queryRes.conv_ws);\n                        if (parsed && parsed[0]) {\n                            const isProj = queryRes.conv_project_id && queryRes.conv_project_id !== \'outside-of-project\';\n                            return { ok: true, isProject: !!isProj, projectId: queryRes.conv_project_id, workspaceUri: parsed[0] };\n                        }\n                    } catch(e) {}\n                }\n            }\n\n            // Fallback: check mapPath if still not resolved\n            if (sectionId && sectionId !== \'outside-of-project\' && fsNode.existsSync(mapPath)) {\n                try {\n                    const map = JSON.parse(fsNode.readFileSync(mapPath, \'utf8\'));\n                    if (map[sectionId]) {\n                        return { ok: true, isProject: true, projectId: sectionId, workspaceUri: map[sectionId] };\n                    }\n                } catch(e) {}\n            }\n\n            return { ok: true, isProject: false, workspaceUri: null };\n        } catch (err) {\n            console.error(\'[antigravity:get-conversation-workspace] Error:\', err);\n            return { ok: false, error: err.message };\n        }\n    });\n\n    electron_1.ipcMain.on(\'antigravity:start-drag\', (event, filePaths) => {\n        try {\n            if (!filePaths) return;\n            const pathNode = require(\'path\');\n            const fsNode = require(\'fs\');\n            const list = (Array.isArray(filePaths) ? filePaths : [filePaths]).map(p => {\n                if (!p || typeof p !== \'string\') return \'\';\n                let clean = p.split(\'#\')[0].split(\'?\')[0];\n                try {\n                    clean = decodeURIComponent(clean);\n                } catch(e) {}\n                if (clean.startsWith(\'file:///\')) {\n                    clean = clean.slice(8);\n                } else if (clean.startsWith(\'file://\')) {\n                    clean = clean.slice(7);\n                }\n                clean = clean.replace(/\\//g, \'\\\\\');\n                if (/^[a-zA-Z]:/.test(clean)) {\n                    clean = clean.charAt(0).toUpperCase() + clean.slice(1);\n                }\n                return pathNode.resolve(clean);\n            }).filter(p => {\n                if (!p) return false;\n                try { return fsNode.existsSync(p); } catch(e) { return false; }\n            });\n\n            if (list.length === 0) return;\n\n            let icon;\n            try {\n                const appIcon = pathNode.join(__dirname, \'../icon.png\');\n                if (fsNode.existsSync(appIcon)) {\n                    icon = electron_1.nativeImage.createFromPath(appIcon);\n                } else {\n                    icon = electron_1.nativeImage.createFromDataURL(\'data:image/png;base64,iVBORw0KGgoAAAANSUhEUgAAACAAAAAgCAYAAABzenr0AAAACXBIWXMAAAsTAAALEwEAmpwYAAAAAXNSR0IArs4c6QAAAARnQU1BAACxjwv8YQUAAABMSURBVHgB7dKxCQAgEERR/13Yv50W0AosJIDM2xve3fWvBwAAAAAAAAAAAN8tC0h0LqGSSuomlFRSy8qSSqqklpUllVRJLX0tAAAAfOEAB28V9k1p4jAAAAAASUVORK5CYII=\');\n                }\n            } catch (e) {\n                icon = electron_1.nativeImage.createEmpty();\n            }\n            event.sender.startDrag({\n                files: list,\n                file: list[0],\n                icon: icon\n            });\n        } catch (err) {\n            console.error(\'[antigravity:start-drag] Error:\', err);\n        }\n    });\n\n    electron_1.ipcMain.handle(\'antigravity:read-dir-entries\', async (_event, dirPath) => {\n        try {\n            const fsNode = require(\'fs\');\n            const pathNode = require(\'path\');\n            const dirents = await fsNode.promises.readdir(dirPath, { withFileTypes: true });\n            const items = [];\n            for (const d of dirents) {\n                // Complete listing: do not hide .git, node_modules, __pycache__, .idea or dot files.\n                items.push({\n                    name: d.name,\n                    path: pathNode.join(dirPath, d.name),\n                    isDirectory: d.isDirectory()\n                });\n            }\n            items.sort((a, b) => {\n                if (a.isDirectory && !b.isDirectory) return -1;\n                if (!a.isDirectory && b.isDirectory) return 1;\n                return a.name.localeCompare(b.name, undefined, { sensitivity: \'base\' });\n            });\n            return items;\n        } catch (err) {\n            return [];\n        }\n    });\n\n    // Workspace Real-Time File Watcher\n    let _activeWorkspaceWatcher = null;\n    let _activeWatchedPath = null;\n    let _watchDebounceTimer = null;\n\n    electron_1.ipcMain.handle(\'antigravity:watch-workspace\', async (event, dirPath) => {\n        try {\n            if (!dirPath || typeof dirPath !== \'string\') return false;\n            const pathNode = require(\'path\');\n            const fsNode = require(\'fs\');\n            const normPath = pathNode.resolve(dirPath);\n            if (_activeWatchedPath === normPath && _activeWorkspaceWatcher) {\n                return true;\n            }\n            if (_activeWorkspaceWatcher) {\n                try { _activeWorkspaceWatcher.close(); } catch(e) {}\n                _activeWorkspaceWatcher = null;\n            }\n            if (!fsNode.existsSync(normPath)) return false;\n\n            _activeWatchedPath = normPath;\n            const senderWebContents = event.sender;\n            _activeWorkspaceWatcher = fsNode.watch(normPath, { recursive: true }, (eventType, filename) => {\n                if (filename && (\n                    filename.endsWith(\'.tmp\') ||\n                    filename.endsWith(\'.crswap\')\n                )) {\n                    return;\n                }\n                clearTimeout(_watchDebounceTimer);\n                _watchDebounceTimer = setTimeout(() => {\n                    try {\n                        if (senderWebContents && !senderWebContents.isDestroyed()) {\n                            senderWebContents.send(\'antigravity:workspace-changed\', {\n                                workspacePath: normPath,\n                                eventType,\n                                filename\n                            });\n                        }\n                    } catch(e) {}\n                }, 300);\n            });\n            return true;\n        } catch(err) {\n            console.error(\'[antigravity:watch-workspace] Error:\', err);\n            return false;\n        }\n    });\n\n    electron_1.ipcMain.handle(\'antigravity:unwatch-workspace\', async () => {\n        try {\n            if (_activeWorkspaceWatcher) {\n                _activeWorkspaceWatcher.close();\n                _activeWorkspaceWatcher = null;\n                _activeWatchedPath = null;\n            }\n            return true;\n        } catch(e) {\n            return false;\n        }\n    });\n\n    electron_1.ipcMain.handle(\'antigravity:reveal-in-explorer\', async (_event, filePath) => {\n        try {\n            const cleanPath = __toCleanLocalPath(filePath);\n            if (!cleanPath) return false;\n            const fsNode = require(\'fs\');\n            const { shell } = require(\'electron\');\n            if (fsNode.existsSync(cleanPath)) {\n                shell.showItemInFolder(cleanPath);\n                return true;\n            }\n            const resolved = __smartResolveLocalPath(cleanPath);\n            if (resolved && resolved.path) {\n                if (resolved.isFile && fsNode.existsSync(resolved.path)) {\n                    shell.showItemInFolder(resolved.path);\n                    return true;\n                } else if (fsNode.existsSync(resolved.path)) {\n                    shell.openPath(resolved.path);\n                    return true;\n                }\n            }\n            return false;\n        } catch (err) {\n            console.error(\'[antigravity:reveal-in-explorer] Error:\', err);\n            return false;\n        }\n    });\n\n    electron_1.ipcMain.handle(\'antigravity:resolve-file-path\', async (_event, filePath) => {\n        try {\n            return __smartResolveLocalPath(filePath);\n        } catch (err) {\n            return null;\n        }\n    });\n'

PRELOAD_BRIDGE_SNIPPET = "\n// ANTIGRAVITY_FS_BRIDGE\ntry {\n    const _workspaceChangeListeners = new Set();\n    electron_1.ipcRenderer.on('antigravity:workspace-changed', (_event, data) => {\n        _workspaceChangeListeners.forEach(listener => {\n            try { listener(data); } catch(e) {}\n        });\n    });\n\n    const antigravityFSAPI = {\n        readFileBytes: (filePath) => electron_1.ipcRenderer.invoke('antigravity:read-file-bytes', filePath),\n        readFileText: (filePath) => electron_1.ipcRenderer.invoke('antigravity:read-file-text', filePath),\n        getOfficeViewerAsset: (assetName) => electron_1.ipcRenderer.invoke('antigravity:get-office-asset', assetName),\n        getConversationTurns: (conversationId) => electron_1.ipcRenderer.invoke('antigravity:get-conversation-turns', conversationId),\n        focusWindow: () => electron_1.ipcRenderer.invoke('antigravity:focus-window'),\n        copyFilesToClipboard: (filePaths) => electron_1.ipcRenderer.invoke('antigravity:copy-files-to-clipboard', filePaths),\n        getConversationWorkspace: (convId, sectionId) => electron_1.ipcRenderer.invoke('antigravity:get-conversation-workspace', convId, sectionId),\n        startDrag: (filePaths) => electron_1.ipcRenderer.send('antigravity:start-drag', filePaths),\n        readDirEntries: (dirPath) => electron_1.ipcRenderer.invoke('antigravity:read-dir-entries', dirPath),\n        watchWorkspace: (dirPath) => electron_1.ipcRenderer.invoke('antigravity:watch-workspace', dirPath),\n        unwatchWorkspace: () => electron_1.ipcRenderer.invoke('antigravity:unwatch-workspace'),\n        revealInExplorer: (filePath) => electron_1.ipcRenderer.invoke('antigravity:reveal-in-explorer', filePath),\n        resolveFilePath: (filePath) => electron_1.ipcRenderer.invoke('antigravity:resolve-file-path', filePath),\n        onWorkspaceChanged: (callback) => {\n            _workspaceChangeListeners.add(callback);\n            return () => _workspaceChangeListeners.delete(callback);\n        }\n    };\n    electron_1.contextBridge.exposeInMainWorld('antigravityFS', antigravityFSAPI);\n} catch (err) {\n    console.error('[AntigravityFS] Bridge expose failed:', err);\n}\n"
